//! Component dumps of the gradient widgets: each one's resolved style (its pure `style` function) in
//! every built-in and mode, as text under `tests/dumps/components/`. Rewrite with
//! `UPDATE_DUMPS=1 cargo test -p craft-draw --features ui --test control_dumps`.

use craft_draw::ui::{GradientEditor, GradientOverlay};
use craft_ui::presets::style::PresetStyle;

use craft_ui::testing::dump::{Dump, check_component};
use craft_ui::theme::UiTokens;

const HEADER: &str =
    "Generated by crates/draw/tests/control_dumps.rs; rewrite with UPDATE_DUMPS=1 cargo test -p craft-draw --features ui --test control_dumps";

fn check(file: &str, each: impl FnMut(&mut Dump, &UiTokens)) {
    check_component(format!("{}/tests/dumps/components/{file}", env!("CARGO_MANIFEST_DIR")), HEADER, each);
}

/// Gradient editors: the bar's sizes, the ramp's checkerboard and edge, the marker colours and
/// the drop line.
#[test]
fn gradient_editor() {
    check("gradient_editor.txt", |d, t| {
        let s = GradientEditor::style(t);
        d.line("ramp_height", s.ramp_height).line("inset", s.inset).line("marker", s.marker).line("pointer", s.pointer).line("diamond", s.diamond);
        d.line("hit", s.hit).line("diamond_hit", s.diamond_hit).line("tear_off", s.tear_off).line("drop_line", s.drop_line);
        d.line("checker_a", s.ramp.checker[0]).line("checker_b", s.ramp.checker[1]).line("cell", s.ramp.cell).line("edge", s.ramp.edge);
        d.line("marker_edge", s.marker_edge).line("hovered", s.hovered).line("selected", s.selected).line("drop", s.drop);
    });
}

/// Gradient lines: the line and its outline, the mirrored dash, the end rings, the stop discs and
/// rings, the diamonds, the selected colour, the hit, click slop and tear-off distances.
#[test]
fn gradient_line() {
    check("gradient_line.txt", |d, t| {
        let s = GradientOverlay::style(t);
        d.line("line", s.line).line("halo", s.halo).line("dash", s.dash.0).line("gap", s.dash.1);
        d.line("end_ring", s.end_ring).line("end", s.end).line("end_halo", s.end_halo);
        d.line("stop", s.stop).line("stop_ring", s.stop_ring).line("stop_halo", s.stop_halo);
        d.line("diamond", s.diamond).line("diamond_fill", s.diamond_fill).line("diamond_halo", s.diamond_halo);
        d.line("selected", s.selected).line("backing", s.backing);
        d.line("hit", s.hit).line("click_slop", s.click_slop).line("tear_off", s.tear_off);
    });
}

#[test]
fn gradient_palette() {
    check("gradient_palette.txt", |d, t| {
        let g = t.component.gradient_palette;
        let ring = PresetStyle::from_tokens(t);
        d.line("cell_width", g.cell_width)
            .line("cell_height", g.cell_height)
            .line("list_swatch_width", g.list_swatch_width)
            .line("list_swatch_height", g.list_swatch_height)
            .line("max_height", g.max_height)
            .line("ring_selected", ring.ring_selected)
            .line("ring_halo", ring.ring_halo);
    });
}
